<section class="card table-card"><div class="table table-responsive"><table><thead><tr><th>Agent</th><th>Versão / status</th><th>Heartbeat</th><th>Poll</th><th>Capabilities</th><th>Última atividade</th></tr></thead><tbody>@forelse($agents as $a)<tr><td data-label="Agent"><div><a href="{{route('agents.show',$a)}}">{{$a->name}}</a><small>{{$a->hostname}}</small></div></td><td data-label="Versão / status"><div><x-badge :value="\App\Web\Presentation::agentStatus($a)"/><small>v{{$a->version}}</small></div></td><td data-label="Heartbeat" class="mono">{{\App\Web\Presentation::age($a->last_heartbeat_at)}}</td><td data-label="Poll" class="mono">{{\App\Web\Presentation::age($a->last_poll_at)}}</td><td data-label="Capabilities"><div><strong>{{count($a->capabilities??[])}} disponíveis</strong><details data-detail-key="caps-{{$a->id}}"><summary>Ver capabilities</summary><div class="chip-list">@foreach($a->capabilities??[] as $cap)<span class="chip">{{$cap}}</span>@endforeach</div></details></div></td><td data-label="Última atividade"><div>@php($last=collect([$a->last_poll_at,$a->last_heartbeat_at])->filter()->sortDesc()->first())@if($last)<time datetime="{{$last->toIso8601String()}}">{{$last->format('d/m H:i:s T')}}</time>@else Sem atividade @endif</div></td></tr>@empty<tr><td colspan="6"><div class="empty"><div class="empty-icon"><x-icon name="agents"/></div><h3>Nenhum Agent neste tenant</h3><p>Cadastre um ponto de observação para iniciar diagnósticos. Não há Agents online a apresentar.</p></div></td></tr>@endforelse</tbody></table></div>@include('shared.pagination',['items'=>$agents])</section>